def capital_final(capital_initial, taux_annuel, annees):
    """Calcul intérêts composés annuels."""
    k = 1 + taux_annuel
    return capital_initial * (k ** annees)

# Exemple : 1000 € à 3% pendant 5 ans
c0 = 1000
t = 0.03
for n in range(1, 6):
    cn = capital_final(c0, t, n)
    print(f"Année {n}: {cn:.2f} €")
